class Solution:
    def nextPermutation(self, nums: list[int]) -> None:
        n = len(nums)
        # 步骤1：从右向左找到第一个 nums[i] < nums[i+1]
        i = n - 2
        while i >= 0 and nums[i] >= nums[i + 1]:
            i -= 1

        if i >= 0:
            # 步骤3：从右向左找到第一个大于 nums[i] 的元素
            j = n - 1
            while nums[j] <= nums[i]:
                j -= 1
            # 步骤4：交换
            nums[i], nums[j] = nums[j], nums[i]

        # 步骤5：反转 i+1 到末尾
        left, right = i + 1, n - 1
        while left < right:
            nums[left], nums[right] = nums[right], nums[left]
            left += 1
            right -= 1
